            "extendApproved": false
          },
          {
            "name": "视频",
            "used": "1小时30分",
            "limit": "限1小时",
            "overLimit": true,
            "extendApproved": true
          }
        ],
        "actionText": "数字健康"
      },
      "assets": {
        "mainIcon": "resources/base/media/icon_tiktok.png"
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "anti_addiction_tiktok_icon",
      "src": "resources/base/media/icon_tiktok.png",
      "use": "anti-addiction app icon",
      "description": "抖音应用语义图标，用于防沉迷应用用量卡片的主视觉识别。",
      "bindTo": "/assets/mainIcon",
      "static": true
    }
  ]
}

